#!/usr/bin/env python3
from pathlib import Path
import base64
import shutil
import sys

if len(sys.argv) != 2:
    raise SystemExit("Usage: python3 add_threshold_network_gallery_fixed.py INSPIRE_petal_name_threshold_grid.Rmd")

path = Path(sys.argv[1]).expanduser().resolve()
if not path.is_file():
    raise SystemExit(f"Rmd file not found: {path}")

text = path.read_text(encoding="utf-8")
marker = "# Selected-threshold INSPIRE results"
section_header = "# Network gallery for every threshold"

if marker not in text:
    raise SystemExit(f"Could not find insertion marker: {marker}")
if section_header in text:
    raise SystemExit("Network gallery is already present. No changes made.")

backup = path.with_suffix(path.suffix + ".gallery.bak")
shutil.copy2(path, backup)
insert = base64.b64decode("").decode("utf-8")
updated = text.replace(marker, insert + "\n" + marker, 1)
path.write_text(updated, encoding="utf-8")

print(f"Updated: {path}")
print(f"Backup:  {backup}")
